    public function getSummary(array$f=[]):array{$o=$this->reconcile($f);$d=$this->getDailyReconciliation($f);$v=$this->getVarianceSummary($f);$p=$this->getDepositPerformance($f);return['period'=>$this->periodPayload($f),'eligible_cash_orders'=>count($o),'matched_entries'=>count(array_filter($o,fn($x)=>in_array($x['match_status'],['exact_match','date_mismatch'],true))),'missing_entries'=>count(array_filter($o,fn($x)=>$x['match_status']==='missing_bookkeeping_entry')),'duplicate_entries'=>count(array_filter($o,fn($x)=>$x['match_status']==='duplicate_bookkeeping_entry')),'amount_mismatches'=>count(array_filter($o,fn($x)=>$x['match_status']==='amount_mismatch')),'requires_review'=>count(array_filter($o,fn($x)=>$x['requires_review'])),'expected_cash_cents'=>array_sum(array_column($o,'expected_cash_cents')),'recorded_cash_cents'=>array_sum(array_column($o,'actual_cash_cents')),'daily_controls'=>$d['summary'],'variance'=>$v,'deposits'=>$p['summary'],'current_risk'=>$this->getOutstandingRisk($f),'scoring_status'=>'not_calculated','financial_calculation'=>'integer_cents','methodology'=>'Direct IDs and exact references are automatic. Amount/date/customer candidates remain owner review only.'];}
    public function getEmployeeSummary(array$f=[]):array{$rows=$this->reconcile($f);$out=[];foreach($rows as$r){$id=(int)($r['created_by_id']??0);$k=(string)$id;if(!isset($out[$k]))$out[$k]=['employee_id'=>$id?:null,'employee_name'=>$r['created_by_name']?:'Insufficient historical data','eligible_cash_orders'=>0,'matched_entries'=>0,'missing_entries'=>0,'late_entries'=>0,'expected_cash_cents'=>0,'recorded_cash_cents'=>0];$out[$k]['eligible_cash_orders']++;$out[$k]['expected_cash_cents']+=$r['expected_cash_cents'];$out[$k]['recorded_cash_cents']+=$r['actual_cash_cents'];if(in_array($r['match_status'],['exact_match','date_mismatch'],true))$out[$k]['matched_entries']++;if($r['match_status']==='missing_bookkeeping_entry')$out[$k]['missing_entries']++;if($r['timing_status']==='late')$out[$k]['late_entries']++;}return array_values($out);}
